//! Linux systemd user-service installation.
//!
//! The unit is generated from the running binary and an already validated
//! configuration file. An existing unit that Tehom did not generate, or that
//! differs from the generated one, is never overwritten or removed.

use anyhow::{Context, Result, bail, ensure};
use std::{
    io::Write,
    path::{Path, PathBuf},
    process::Command,
};

pub const UNIT_NAME: &str = "tehom.service";
const MARKER: &str =
    "# Generated by `tehom service install`; remove with `tehom service uninstall`.";

/// Directory that holds systemd user units (`$XDG_CONFIG_HOME/systemd/user`).
pub fn unit_directory() -> Result<PathBuf> {
    let config = directories::BaseDirs::new()
        .context("Kullanıcı yapılandırma klasörü belirlenemedi")?
        .config_dir()
        .to_path_buf();
    Ok(config.join("systemd").join("user"))
}

fn quoted(path: &Path) -> Result<String> {
    let text = path.to_str().context("Servis yolu geçerli UTF-8 olmalı")?;
    ensure!(path.is_absolute(), "Servis yolu mutlak olmalı: {text}");
    // systemd expands `%` specifiers and `$` variables and treats quotes and
    // backslashes specially; refuse them instead of attempting to escape.
    ensure!(
        !text
            .chars()
            .any(|c| matches!(c, '"' | '\\' | '%' | '$' | '\'') || c.is_control()),
        "Servis yolu desteklenmeyen karakter içeriyor: {text}"
    );
    Ok(format!("\"{text}\""))
}

/// Builds the unit text for `binary daemon --config config`.
pub fn unit(binary: &Path, config: &Path) -> Result<String> {
    Ok(format!(
        "{MARKER}
[Unit]
Description=Tehom local channel automation
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecStart={} daemon --config {}
Restart=on-failure
RestartSec=10
KillMode=control-group
TimeoutStopSec=180
UMask=0077

[Install]
WantedBy=default.target
",
        quoted(binary)?,
        quoted(config)?
    ))
}

#[derive(Debug, PartialEq, Eq)]
pub enum Installed {
    Created,
    AlreadyPresent,
}

/// Writes the unit without replacing any existing file.
pub fn install(directory: &Path, text: &str) -> Result<Installed> {
    std::fs::create_dir_all(directory)
        .with_context(|| format!("{} oluşturulamadı", directory.display()))?;
    let target = directory.join(UNIT_NAME);
    match std::fs::read(&target) {
        Ok(existing) if existing == text.as_bytes() => return Ok(Installed::AlreadyPresent),
        Ok(_) => bail!(
            "{} zaten var ve farklı; mevcut dosya değiştirilmedi. Önce `tehom service uninstall` çalıştırın veya dosyayı elle inceleyin.",
            target.display()
        ),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(error).context("Mevcut servis dosyası okunamadı"),
    }
    let temporary = directory.join(format!(".{UNIT_NAME}.{}.tmp", std::process::id()));
    let result = (|| -> Result<()> {
        let mut file = std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temporary)?;
        file.write_all(text.as_bytes())?;
        file.sync_all()?;
        // A hard link fails if the target appeared meanwhile, so nothing is clobbered.
        std::fs::hard_link(&temporary, &target)
            .with_context(|| format!("{} yazılamadı", target.display()))?;
        Ok(())
    })();
    let _ = std::fs::remove_file(&temporary);
    result?;
    Ok(Installed::Created)
}

#[derive(Debug, PartialEq, Eq)]
pub enum Removed {
    Removed,
    NotInstalled,
}

/// Removes the unit only when Tehom generated it.
pub fn uninstall(directory: &Path) -> Result<Removed> {
    let target = directory.join(UNIT_NAME);
    let text = match std::fs::read_to_string(&target) {
        Ok(text) => text,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Ok(Removed::NotInstalled);
        }
        Err(error) => return Err(error).context("Servis dosyası okunamadı"),
    };
    ensure!(
        text.lines().next() == Some(MARKER),
        "{} Tehom tarafından oluşturulmamış; dosya silinmedi.",
        target.display()
    );
    std::fs::remove_file(&target)?;
    Ok(Removed::Removed)
}

/// Runs `systemctl --user` with an argument array and reports failures.
pub fn systemctl(args: &[&str]) -> Result<()> {
    let status = Command::new("systemctl")
        .arg("--user")
        .args(args)
        .status()
        .context("systemctl çalıştırılamadı")?;
    ensure!(
        status.success(),
        "systemctl --user {} başarısız: {status}",
        args.join(" ")
    );
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn unit_quotes_absolute_paths_and_rejects_specifiers() {
        let text = unit(
            Path::new("/home/u/.local/bin/tehom"),
            Path::new("/home/u/.config/tehom/tehom.toml"),
        )
        .unwrap();
        assert!(text.starts_with(MARKER));
        assert!(text.contains(
            "ExecStart=\"/home/u/.local/bin/tehom\" daemon --config \"/home/u/.config/tehom/tehom.toml\""
        ));
        assert!(unit(Path::new("relative/tehom"), Path::new("/c.toml")).is_err());
        for bad in [
            "/a%h/c.toml",
            "/a$HOME/c.toml",
            "/a\"b/c.toml",
            "/a\nb.toml",
        ] {
            assert!(
                unit(Path::new("/bin/tehom"), Path::new(bad)).is_err(),
                "{bad}"
            );
        }
    }

    #[test]
    fn install_never_overwrites_and_uninstall_only_removes_own_unit() {
        let folder = tempfile::tempdir().unwrap();
        let directory = folder.path().join("systemd/user");
        let text = unit(Path::new("/bin/tehom"), Path::new("/c.toml")).unwrap();
        assert_eq!(install(&directory, &text).unwrap(), Installed::Created);
        assert_eq!(
            install(&directory, &text).unwrap(),
            Installed::AlreadyPresent
        );
        let other = unit(Path::new("/bin/tehom"), Path::new("/other.toml")).unwrap();
        assert!(install(&directory, &other).is_err());
        assert_eq!(
            std::fs::read_to_string(directory.join(UNIT_NAME)).unwrap(),
            text
        );
        assert_eq!(uninstall(&directory).unwrap(), Removed::Removed);
        assert_eq!(uninstall(&directory).unwrap(), Removed::NotInstalled);

        let handwritten = "[Service]\nExecStart=/usr/bin/true\n";
        std::fs::write(directory.join(UNIT_NAME), handwritten).unwrap();
        assert!(uninstall(&directory).is_err());
        assert!(install(&directory, &text).is_err());
        assert_eq!(
            std::fs::read_to_string(directory.join(UNIT_NAME)).unwrap(),
            handwritten
        );
        assert_eq!(std::fs::read_dir(&directory).unwrap().count(), 1);
    }
}
